        return Approval.NEEDS_APPROVAL;
    }
    boolean lapsed = approvedOn != null && today.isAfter(approvedOn.plusDays(APPROVAL_DAYS));
    return lapsed ? Approval.NEEDS_APPROVAL : Approval.APPROVED;
}

